/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.lang.reflect.Field;import java.util.ArrayList;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.anno.CtrlItem;import page2020.anno.Form2020;import page2020.anno.FormProp;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.H5;public class Result extends Name<Result> {	private static Logger log = LoggerFactory.getLogger(Result.class);	public static final int success = 1;	public static final int warning = 2;	public static final int error = 3;	private FormProp prop;	private Object entity;	private List<Field> fields;	private List<String> displayNames;	private int status = 0;	private Exception exception;	private List<Content<?>> contents = new ArrayList<Content<?>>(); 	private String action;	public Result(Object entity) {		this(entity, null);	}	public Result(Object entity, String name) {		if (entity == null) {			log.error("Result: argument(entity) is empty !");			return;		}		Class<?> clazz = entity.getClass();		if (clazz.isAnnotationPresent(Form2020.class)) {			FormProp prop = new FormProp(clazz, name);			super.name(prop.getName());			this.prop = prop;			this.entity = entity;			this.fields = prop.getDisplayFields();			this.displayNames = prop.getDisplayNames();		} else {			log.error("Result: '" + clazz.getSimpleName() + "' is NOT in messages.properties !");		}	}	public Result automate(int code) {		if (this.prop == null) {			return null;			}		this.contents.add(H5.code(App.classKey(super.getName())));		if (! this.fields.isEmpty()) {			this.contents.add(H5.text("("));			int size = this.fields.size();			for (int i=0; i < size; i++) {				Object value = null;				try {					value = this.fields.get(i).get(entity);				} catch (Exception ex) {}				if (value == null) {					value = new String("");				}				if (i > 0) {					this.contents.add(H5.text(", "));				}				String phraseCode = App.fieldKey(super.getName(), this.displayNames.get(i));				if (phraseCode != null) {					this.contents.add(H5.code(phraseCode));					this.contents.add(H5.text(": \""));					this.contents.add(H5.value(value));					this.contents.add(H5.text("\""));				}			}			this.contents.add(H5.text(")"));		}		switch (this.status) {		case success:			this.method(code);			this.contents.add(H5.code("page2020.result.success"));			break;		case warning:			this.contents.add(H5.code("page2020.result.warning"));			break;		case error:			this.method(code);			this.contents.add(H5.code("page2020.result.error"));			this.contents.add(H5.br());			this.contents.add(H5.small().text(this.exception.toString()));			break;		}		if (Log.data) {			log.info("Result('" + super.getName() + "') : code=" + code + ", status=" + this.status);		}				return this;	}	public boolean isSuccess() {		return success == this.status; 	}	public Result success() {		this.status = success;		if (Log.data) {			log.info("Result('" + super.getName() + "') : success()");		}		return this;	}	public Result warning() {		this.status = warning;		if (Log.data) {			log.info("Result('" + super.getName() + "') : warning()");		}		return this;	}	public Result error(Exception ex) {		this.status = error;		this.exception = ex;		log.error("Result(" + super.getName() + ") : " + ex.toString());		if (Log.data) {			log.info("Result('" + super.getName() + "') : error()");		}		return this;	}	public Result add(String key) {		if (EmptyUtil.is(key)) {			log.error("add: argument(key) is empty !");			return this;		}		if (! this.displayNames.contains(key)) {			CtrlItem item = null;			int size = this.prop.count();			for (int i=0; i < size; i++) {				item = this.prop.value(i);				if (item.getFieldName().equals(key)) {					this.fields.add(item.getField());					this.displayNames.add(item.getFieldName());					if (Log.data) {						log.info("Result(" + super.getName() + ") : add('" + key + "')");					}								}			}			if (item == null) {				log.error("add: key='" + key + "' is NOT a Field !");			}		}		return this;	}	public Result remove(String key) {		if (EmptyUtil.is(key)) {			log.error("add: argument(key) is empty !");			return this;		}		if (this.displayNames.contains(key)) {			int index = this.displayNames.indexOf(key);			this.fields.remove(index);			this.displayNames.remove(index);			if (Log.data) {				log.info("Result(" + super.getName() + ") : remove('" + key + "')");			}		} else {			log.error("remove: key='" + key + "' is NOT a Key !");		}		return this;	}	private void method(int code) {		switch (code) {		case Code.insert:			this.contents.add(H5.code("page2020.result.insert"));			break;		case Code.update:			this.contents.add(H5.code("page2020.result.update"));			break;		case Code.deleted:			this.contents.add(H5.code("page2020.result.delete"));			break;		default:			this.contents.add(H5.code("page2020.result.execute"));			break;		}	}	public int getStatus() {		return status;	}	public void setStatus(int status) {		this.status = status;	}	public List<Content<?>> getContents() {		return contents;	}	public void setContents(List<Content<?>> contents) {		this.contents = contents;	}	public String getAction() {		return action;	}	public void setAction(String action) {		this.action = action;	}}